-- check.sql — self-check for: Exercise 1 — a small sales database from a description
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 5 checks ──────────';

-- CHECK 1: Defaults: city Hà Nội, stock 0, status NEW, orderDate today; ids generated
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN;
INSERT INTO dbo.Customer (customerID, fullName) VALUES (''KH001'', N''An'');
INSERT INTO dbo.Product (productName, price) VALUES (N''Bút bi'', 5000);
INSERT INTO dbo.Orders (customerID) VALUES (''KH001'');
SET @ok = IIF((SELECT city FROM dbo.Customer WHERE customerID = ''KH001'') = N''Hà Nội''
  AND (SELECT stock FROM dbo.Product WHERE productName = N''Bút bi'') = 0
  AND EXISTS (SELECT 1 FROM dbo.Orders WHERE customerID = ''KH001'' AND status = ''NEW'' AND orderDate = CAST(GETDATE() AS DATE) AND orderID IS NOT NULL), 1, 0);
SET @info = N''a row inserted with only the compulsory columns must get the defaults'';
ROLLBACK;',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. Defaults: city Hà Nội, stock 0, status NEW, orderDate today; ids generated | Mặc định: city Hà Nội, stock 0, status NEW, orderDate hôm nay; id tự sinh'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. Defaults: city Hà Nội, stock 0, status NEW, orderDate today; ids generated | Mặc định: city Hà Nội, stock 0, status NEW, orderDate hôm nay; id tự sinh', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: Two customers without e-mail are allowed; a shared e-mail is rejected
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @hai BIT = 0, @trung BIT = 0;
BEGIN TRAN;
BEGIN TRY INSERT INTO dbo.Customer (customerID, fullName) VALUES (''KH001'', N''An''), (''KH002'', N''Bình''); SET @hai = 1; END TRY BEGIN CATCH END CATCH;
BEGIN TRY INSERT INTO dbo.Customer (customerID, fullName, email) VALUES (''KH003'', N''Chi'', ''x@a.vn''), (''KH004'', N''Dũng'', ''x@a.vn''); END TRY BEGIN CATCH SET @trung = 1; END CATCH;
IF @@TRANCOUNT > 0 ROLLBACK;
SET @ok = IIF(@hai = 1 AND @trung = 1, 1, 0);
SET @info = CONCAT(N''two NULL e-mails accepted: '', @hai, N'' · duplicate e-mail rejected: '', @trung, N'' — a UNIQUE constraint allows only one NULL on SQL Server'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. Two customers without e-mail are allowed; a shared e-mail is rejected | Hai khách không e-mail được phép; e-mail dùng chung bị từ chối'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. Two customers without e-mail are allowed; a shared e-mail is rejected | Hai khách không e-mail được phép; e-mail dùng chung bị từ chối', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: Product rules: price 0, negative stock and a duplicate name are rejected
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @n INT = 0;
BEGIN TRAN;
BEGIN TRY INSERT INTO dbo.Product (productName, price) VALUES (N''A'', 0); END TRY BEGIN CATCH SET @n += 1; END CATCH;
BEGIN TRY INSERT INTO dbo.Product (productName, price, stock) VALUES (N''B'', 10, -1); END TRY BEGIN CATCH SET @n += 1; END CATCH;
BEGIN TRY INSERT INTO dbo.Product (productName, price) VALUES (N''C'', 10), (N''C'', 20); END TRY BEGIN CATCH SET @n += 1; END CATCH;
IF @@TRANCOUNT > 0 ROLLBACK;
SET @ok = IIF(@n = 3, 1, 0); SET @info = CONCAT(@n, N'' of 3 invalid statements were rejected'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. Product rules: price 0, negative stock and a duplicate name are rejected | Luật sản phẩm: giá 0, tồn âm, tên trùng bị từ chối'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. Product rules: price 0, negative stock and a duplicate name are rejected | Luật sản phẩm: giá 0, tồn âm, tên trùng bị từ chối', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 4: Order rules: unknown customer, status SHIPPED, quantity 0, same product twice are rejected
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'BEGIN TRAN;
INSERT INTO dbo.Customer (customerID, fullName) VALUES (''KH001'', N''An'');
INSERT INTO dbo.Product (productName, price) VALUES (N''Bút'', 5000);
