DECLARE @n INT = 0;
BEGIN TRY INSERT INTO dbo.Orders (customerID) VALUES (''KH999''); END TRY BEGIN CATCH SET @n += 1; END CATCH;
BEGIN TRY INSERT INTO dbo.Orders (customerID, status) VALUES (''KH001'', ''SHIPPED''); END TRY BEGIN CATCH SET @n += 1; END CATCH;
BEGIN TRY INSERT INTO dbo.OrderLine VALUES (@o, @p, 0, 5000); END TRY BEGIN CATCH SET @n += 1; END CATCH;
BEGIN TRY INSERT INTO dbo.OrderLine VALUES (@o, @p, 1, 5000), (@o, @p, 2, 5000); END TRY BEGIN CATCH SET @n += 1; END CATCH;
IF @@TRANCOUNT > 0 ROLLBACK;
SET @ok = IIF(@n = 4, 1, 0); SET @info = CONCAT(@n, N'' of 4 invalid statements were rejected'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 4. Order rules: unknown customer, status SHIPPED, quantity 0, same product twice are rejected | Luật đơn: khách lạ, trạng thái SHIPPED, số lượng 0, trùng sản phẩm bị từ chối'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 4. Order rules: unknown customer, status SHIPPED, quantity 0, same product twice are rejected | Luật đơn: khách lạ, trạng thái SHIPPED, số lượng 0, trùng sản phẩm bị từ chối', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 5: customerID is exactly CHAR(5); productID and orderID are IDENTITY
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.Customer'') AND c.name = N''customerID'' AND t.name = N''char'' AND c.max_length = 5)
  AND COLUMNPROPERTY(OBJECT_ID(N''dbo.Product''), ''productID'', ''IsIdentity'') = 1
  AND COLUMNPROPERTY(OBJECT_ID(N''dbo.Orders''), ''orderID'', ''IsIdentity'') = 1, 1, 0);
SET @info = N''expected customerID CHAR(5), productID and orderID IDENTITY'';',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 5. customerID is exactly CHAR(5); productID and orderID are IDENTITY | customerID đúng CHAR(5); productID và orderID là IDENTITY'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 5. customerID is exactly CHAR(5); productID and orderID are IDENTITY | customerID đúng CHAR(5); productID và orderID là IDENTITY', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);

